void mainImage(out vec4 O, vec2 I) {
    vec2 uv = I / iResolution.xy;

    vec3 scene = texture(iChannel0, uv).rgb;

    vec3 bloom = vec3(0.0);
    vec2 off = 1.5 / iResolution.xy;
    bloom += texture(iChannel0, uv + vec2(-off.x, -off.y)).rgb * 0.15;
    bloom += texture(iChannel0, uv + vec2( off.x, -off.y)).rgb * 0.15;
    bloom += texture(iChannel0, uv + vec2(-off.x,  off.y)).rgb * 0.15;
    bloom += texture(iChannel0, uv + vec2( off.x,  off.y)).rgb * 0.15;
    bloom += texture(iChannel0, uv + vec2(0.0, -off.y * 2.0)).rgb * 0.1;
    bloom += texture(iChannel0, uv + vec2(0.0,  off.y * 2.0)).rgb * 0.1;

    vec3 col = scene + bloom * 0.65;

    col = tanh(col * col * 0.08);

    vec2 dist = uv - 0.5;
    col *= 1.0 - dot(dist, dist) * 0.8;

    col = pow(col, vec3(0.95));

    vec2 centeredUV = (I - 0.5 * iResolution.xy) / iResolution.y + 0.5;
    float cdMask = drawCountdown(centeredUV, iTime);

    vec3 textCol = mix(vec3(0.0, 0.9, 1.0), vec3(1.0, 0.1, 0.4), sin(iTime * 10.0) * 0.5 + 0.5);
    if (iTime >= 12.0 && iTime < 14.0) {
        textCol = vec3(1.0, 0.8, 0.0);
    }

    col = mix(col, textCol + vec3(0.5), cdMask);

    O = vec4(col, 1.0);
}

vec3 hash31(float p) {
    vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xxx + p3.yzx) * p3.zyx);
}

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float drawSegment(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return smoothstep(0.08, 0.02, length(pa - ba * h));
}

float draw7Seg(vec2 p, int num) {
    p = (p - vec2(0.5, 0.5)) * 2.2;
    float mask = 0.0;

    bool segA = (num==0||num==2||num==3||num==5||num==6||num==7||num==8||num==9);
    bool segB = (num==0||num==1||num==2||num==3||num==4||num==7||num==8||num==9);
    bool segC = (num==0||num==1||num==3||num==4||num==5||num==6||num==7||num==8||num==9);
    bool segD = (num==0||num==2||num==3||num==5||num==6||num==8||num==9);
    bool segE = (num==0||num==2||num==6||num==8);
    bool segF = (num==0||num==4||num==5||num==6||num==8||num==9);
    bool segG = (num==2||num==3||num==4||num==5||num==6||num==8||num==9);

    if(segA) mask += drawSegment(p, vec2(-0.35,  0.7), vec2( 0.35,  0.7));
    if(segB) mask += drawSegment(p, vec2( 0.35,  0.7), vec2( 0.35,  0.0));
    if(segC) mask += drawSegment(p, vec2( 0.35,  0.0), vec2( 0.35, -0.7));
    if(segD) mask += drawSegment(p, vec2(-0.35, -0.7), vec2( 0.35, -0.7));
    if(segE) mask += drawSegment(p, vec2(-0.35,  0.0), vec2(-0.35, -0.7));
    if(segF) mask += drawSegment(p, vec2(-0.35,  0.7), vec2(-0.35,  0.0));
    if(segG) mask += drawSegment(p, vec2(-0.35,  0.0), vec2( 0.35,  0.0));

    return clamp(mask, 0.0, 1.0);
}

float drawG(vec2 p) {
    p = (p - vec2(0.5, 0.5)) * 2.2;
    float m = 0.0;
    m += drawSegment(p, vec2(-0.35,  0.7), vec2( 0.35,  0.7));
    m += drawSegment(p, vec2(-0.35,  0.7), vec2(-0.35, -0.7));
    m += drawSegment(p, vec2(-0.35, -0.7), vec2( 0.35, -0.7));
    m += drawSegment(p, vec2( 0.35, -0.7), vec2( 0.35,  0.0));
    m += drawSegment(p, vec2( 0.0,   0.0), vec2( 0.35,  0.0));
    return clamp(m, 0.0, 1.0);
}

float drawO(vec2 p) {
    p = (p - vec2(0.5, 0.5)) * 2.2;
    float m = 0.0;
    m += drawSegment(p, vec2(-0.35,  0.7), vec2( 0.35,  0.7));
    m += drawSegment(p, vec2( 0.35,  0.7), vec2( 0.35, -0.7));
    m += drawSegment(p, vec2(-0.35, -0.7), vec2( 0.35, -0.7));
    m += drawSegment(p, vec2(-0.35,  0.7), vec2(-0.35, -0.7));
    return clamp(m, 0.0, 1.0);
}

float drawExcl(vec2 p) {
    p = (p - vec2(0.5, 0.5)) * 2.2;
    float m = 0.0;
    m += drawSegment(p, vec2(0.0, 0.7), vec2(0.0, -0.2));
    m += drawSegment(p, vec2(0.0, -0.55), vec2(0.0, -0.7));
    return clamp(m, 0.0, 1.0);
}

float drawCountdown(vec2 uv, float t) {
    if (t > 14.0) return 0.0;

    vec2 p = uv;
    float pulse = fract(t);
    float scale = 1.0 + (1.0 - pulse) * 0.15;
    p = (p - 0.5) / scale + 0.5;

    if (t < 12.0) {
        int count = 12 - int(floor(t));
        if (count >= 10) {
            float d1 = draw7Seg(p * vec2(1.8, 1.0) - vec2(-0.35, 0.0), 1);
            float d2 = draw7Seg(p * vec2(1.8, 1.0) - vec2(0.55, 0.0), count - 10);
            return clamp(d1 + d2, 0.0, 1.0);
        } else {
            return draw7Seg(p, count);
        }
    } else if (t < 14.0) {
        float g = drawG(p * vec2(2.5, 1.0) - vec2(-0.75, 0.0));
        float o = drawO(p * vec2(2.5, 1.0) - vec2(0.25, 0.0));
        float ex = drawExcl(p * vec2(2.5, 1.0) - vec2(1.25, 0.0));
        return clamp(g + o + ex, 0.0, 1.0);
    }
    return 0.0;
}

void mainImage(out vec4 O, vec2 I) {
    float kick = texture(iChannel0, vec2(0.01, 0.25)).x;
    float hihat = texture(iChannel0, vec2(0.85, 0.25)).x;

    float bassAmp = pow(kick, 2.5);
    float hatAmp = pow(hihat, 2.0);

    float T = iTime * 0.6 + bassAmp * 0.2;
    float t1 = T * 0.19, t2 = T * -0.13;

    float triggerStrobo = step(0.35, bassAmp);
    float microPulse = hatAmp * 0.5;
    float etatStrobo = clamp(triggerStrobo + microPulse, 0.0, 1.0);

    float idSeed = floor(iTime * 10.0 + hatAmp * 20.0);
    vec3 couleurFlash = hash31(idSeed);
    couleurFlash = mix(couleurFlash, vec3(1.0, 0.2, 0.8), hatAmp * 0.6);

    vec2 uv = (I + I - iResolution.xy) / iResolution.y;

    vec2 camShake = (hash31(iTime).xy - 0.5) * bassAmp * 0.12;
    uv += camShake;

    vec3 p, dir = normalize(vec3(uv, 1.0));

    float z = 1.5 - bassAmp * 0.35;
    vec3 colAcc = vec3(0.0);
    mat2 R1 = rot2D(t1);
    mat2 R2 = rot2D(t2 + bassAmp * 0.15);

    for (float i = 0.0; i < 96.0; i++) {
        p = z * dir;
        p.yz *= R1;
        p.xz *= R2;

        vec3 q = p * 0.22;
        float k = 0.3;

        for (int j = 0; j < 8; j++) {
            q = -1.0 + 2.0 * fract(0.5 * q + 0.5);
            float r2 = dot(q, q);
            float f = clamp(1.0 / max(r2, 0.0001), 1.0, 8.0);
            q *= f;
            k *= f;
        }

        float d = 0.01 + abs(length(q) - 0.25) / (k * 3.5);
        z += d;

        vec3 col = couleurFlash * (cos(length(q) * 1.4 + t2) + 0.5 + bassAmp * 0.6);
        colAcc += (col / (d * z * (24.0 - bassAmp * 10.0))) * etatStrobo;

        if (z > 20.0) break;
    }

    O = vec4(colAcc, z);
}
